 const tokenEnd=source.indexOf('>',end);if(tokenEnd<0)return null;const token=source.slice(open,tokenEnd+1),opening=token.match(/^<([A-Za-z_][\w:.-]*)([^>]*)>$/);if(!opening||opening[1]!==oldTag||opening[2].trimEnd().endsWith('/'))return null;
