 const packages=new Map();for(const j of jobs){const key=j.package_id||j.package_name||'legacy';if(!packages.has(key))packages.set(key,{name:j.package_name||'Previously imported',list:[]});packages.get(key).list.push(j)}
 $('#jobs').innerHTML=[...packages.values()].map(pkg=>`<div class="package-title" title="${esc(pkg.name)}">▣ ${esc(pkg.name)}</div><div class="queue-title">General · ${pkg.list.length}</div>${pkg.list.map(j=>`<div class="job-row"><input type="checkbox" data-select-job="${j.id}" aria-label="Select ${esc(j.article_id)}" ${selectedJobs.has(j.id)?'checked':''}><button class="job ${J?.id===j.id?'active':''}" data-job="${j.id}"><strong>${esc(j.article_id)}</strong><small>${esc(j.title||j.progress)}</small><span class="mini">${j.status==='READY'?j.author_count+' authors · '+j.reference_count+' refs · '+j.issues+' issues':esc(j.status.replaceAll('_',' '))}</span><span class="queue-pill regular">GENERAL · ${j.matched||0}/${j.total||0}</span></button></div>`).join('')}`).join('');
