 $('#heading').textContent=J?J.article_id:jobs.length?'All files':'Your citation workspace';
 $('#header-actions').innerHTML=J?'<button id="queue-home">← All files</button> '+(J.status==='READY'?'<button id="reextract">Re-extract PDF</button> <button id="clear-one" class="danger">Clear file</button> <button id="export-open" class="primary">Export XML</button>':''):'';
 if($('#queue-home'))$('#queue-home').onclick=showQueue;
 if($('#export-open'))$('#export-open').onclick=exportDialog;
 if($('#reextract'))$('#reextract').onclick=async()=>{if(dirty||xmlDirty){toast('Save or discard pending edits before re-extracting.');return}const warning=J.manual_xml?' This will also replace the current manual XML; the saved revision can be restored.':'';if(!confirm('Re-extract the selected PDF and rebuild metadata/XML from the original sources? The current revision will be saved for recovery.'+warning))return;try{J=await action({action:'reextract',confirmed:true});paint();await loadJobs();toast('Re-extraction started. The previous revision is saved in History.')}catch(e){toast(e.message)}};
