 const fileNo=jobs.findIndex(j=>j.id===J.id)+1;
 $('#article-bar').innerHTML=`<span class="title" title="${esc(J.metadata.title)}">${esc(J.metadata.title)}</span><span class="badge ok">GENERAL · ${J.triage?.matched||0}/${J.triage?.total||0} matches</span><span>File ${fileNo} · ${J.metadata.authors.length} authors · ${J.metadata.references.length} references · ${(J.issues||[]).filter(i=>i.status==='OPEN').length} informational issues</span>`;
