async function importFiles(files){
 if(!files.length)return;if(importing){toast('Wait for the current import to finish.');return}
 if(files.length>2500){toast('Select at most 2,500 files per import.');return}
 if(files.filter(f=>(f.file||f).name.toLowerCase().endsWith('.zip')).length>50){toast('Select up to 50 ZIP packages per import.');return}
 importing=true;const batch=uid();
 try{for(let i=0;i<files.length;i++){const f=files[i].file||files[i],name=files[i].path||f.webkitRelativePath||f.name;toast('Importing '+(i+1)+' / '+files.length+' · '+name);const r=await fetch('/api/upload?batch='+batch+'&name='+encodeURIComponent(name),{method:'POST',headers:{'X-ICE-Token':session.token},body:f});if(!r.ok)throw new Error((await r.json()).error)}
 const result=lastImport=await api('/api/process',{batch});$('#import-report').hidden=false;await loadJobs();if(result.jobs.length)showQueue();toast(result.jobs.length+' article(s) imported'+(result.ignored.length?' · See import report for skipped files.':''));
 if(!result.jobs.length||result.ignored.length)showImportReport();
 }catch(e){modal('Import needs attention','<p>'+esc(e.message)+'</p><p>Your source files have not been changed. For a folder, use Import folder or import its ZIP.</p>')}finally{importing=false}
}
async function droppedFiles(dataTransfer){
 const entries=[...dataTransfer.items||[]].map(i=>i.webkitGetAsEntry?.()).filter(Boolean);
 if(!entries.length)return [...dataTransfer.files];
 const files=[];
 async function visit(entry,path=''){
  if(files.length>=2500)throw new Error('Too many files. Split the folder into smaller batches.');
  if(entry.isFile){const file=await new Promise((resolve,reject)=>entry.file(resolve,reject));files.push({file,path:path+entry.name});}
  else if(entry.isDirectory){const reader=entry.createReader();while(true){const children=await new Promise((resolve,reject)=>reader.readEntries(resolve,reject));if(!children.length)break;for(const child of children)await visit(child,path+entry.name+'/');}}
 }
 for(const entry of entries)await visit(entry);
 return files;
}
