async function showRules(){
 const d=await api('/api/rules'),groups=[...new Set(d.rules.map(r=>r.group))],shown=v=>Array.isArray(v)?v.join(', '):String(v);
 modal('Matching rules',`<p class="small muted">Every file stays in the General queue. These rules compare article metadata with its source documents and show matches or differences for review; they do not move files between queues. XML is generated automatically for files without direct XML edits.</p><p class="small">To change matching rules, edit <b>${esc(d.path)}</b> in a text editor and save it. Choose Match & regenerate XML to apply them to existing files.</p>${d.errors.length?`<div class="notice"><b class="danger">Rulebook errors affect matching results:</b>${d.errors.map(e=>`<p class="small">${esc(e)}</p>`).join('')}</div>`:''}<div class="toolbar"><button class="primary" id="recheck">Match & regenerate XML</button><span class="small muted">${d.rules.filter(r=>r.on).length} of ${d.rules.length} rules on</span></div>${groups.map(g=>`<h3>${esc(g)}</h3>${d.rules.filter(r=>r.group===g).map(r=>`<div class="card"><span class="badge ${r.on?'ok':''}" style="float:right">${r.on?'On':r.missing?'Off · not in file':'Off'}</span><b>${esc(r.text)}</b><p class="small muted">[${esc(r.key)}]${Object.entries(r.settings).map(([k,v])=>` · ${esc(k)} = ${esc(shown(v))}`).join('')}</p></div>`).join('')}`).join('')}`);
 $('#recheck').onclick=async()=>{$('#recheck').disabled=true;try{const r=await api('/api/recheck',{});await loadJobs();if(J&&!dirty&&!xmlDirty){J=await api('/api/jobs/'+J.id);paint()}toast(`Matched ${r.checked} file(s); regenerated ${r.regenerated} XML file(s); retrying ${r.retrying} failed file(s).`+(r.manual_xml_preserved?` Preserved ${r.manual_xml_preserved} manually edited XML file(s).`:'')+(r.failures?.length?` ${r.failures.length} XML regeneration failure(s).`:''))}catch(e){toast(e.message)}finally{if($('#recheck'))$('#recheck').disabled=false}};
}
async function exportDialog(){
 if(dirty||xmlDirty){if(!confirm('Save your pending metadata/XML changes before export?'))return;try{await saveXML();if(dirty)await saveMetadata()}catch(e){toast(e.message);return}}
 modal('Export this article',`<div class="notice blue">Export uses the current saved XML and includes any informational findings in the audit files. Validation results do not block export.</div><div class="toolbar"><button class="primary" id="download-xml">Download XML</button><button id="download-zip">XML + audit ZIP</button></div>`);
 async function run(format){try{const r=await fetch('/api/jobs/'+J.id,{method:'POST',headers:{'Content-Type':'application/json','X-ICE-Token':session.token},body:JSON.stringify({action:'export',revision:J.revision,format})});if(!r.ok)throw new Error((await r.json()).error);const name=(r.headers.get('content-disposition')||'').match(/filename="([^"]+)"/)?.[1]||'export.zip';downloadBlob(await r.blob(),name);$('#dialog').close();toast('Export saved.');await loadJobs()}catch(e){toast(e.message)}}
 $('#download-xml').onclick=()=>run('xml');$('#download-zip').onclick=()=>run('zip');
}
async function exportCurrentXML(){
 if(dirty||xmlDirty){await saveMetadata();if(dirty||xmlDirty)return}
 try{const r=await fetch('/api/jobs/'+J.id,{method:'POST',headers:{'Content-Type':'application/json','X-ICE-Token':session.token},body:JSON.stringify({action:'export',revision:J.revision,format:'xml'})});if(!r.ok)throw new Error((await r.json()).error);const name=(r.headers.get('content-disposition')||'').match(/filename="([^"]+)"/)?.[1]||((J.article_id||'article')+'.xml');downloadBlob(await r.blob(),name);toast('XML exported.')}catch(e){toast(e.message)}
}
function toggleFullscreen(el){if(document.fullscreenElement)document.exitFullscreen();else el?.requestFullscreen?.().catch(e=>toast(e.message))}
function applyWorkspacePanels(){
 const ws=$('#workspace');if(!ws)return;
 const specs=[['support','#support-rail','var(--support-width)'],['pdf','.source-panel','minmax(320px,1fr)'],['xml','#review-panel','var(--review-width)']];
 const visible=specs.filter(([key])=>workspacePanels[key]);let cols=[],column=1;
 for(let i=0;i<visible.length;i++){
  const [key,selector,width]=visible[i],el=$(selector);el.hidden=false;el.style.gridColumn=String(column++);
  cols.push(width);
  if(i<visible.length-1){const next=visible[i+1][0],grip=key==='support'||next==='support'?'#support-grip':'#review-grip',g=$(grip);g.hidden=false;g.style.gridColumn=String(column++);cols.push('5px')}
 }
 for(const [key,selector] of specs)if(!workspacePanels[key]){$(selector).hidden=true;$(selector).style.gridColumn=''}
 for(const id of ['support-grip','review-grip']){$('#'+id).hidden=true;$('#'+id).style.gridColumn=''}
 for(let i=0;i<visible.length-1;i++){const a=visible[i][0],b=visible[i+1][0],id=(a==='support'||b==='support')?'support-grip':'review-grip';const el=$('#'+id);el.hidden=false;el.style.gridColumn=String(2+i*2)}
 ws.style.gridTemplateColumns=cols.join(' ');ws.classList.toggle('workspace-single',visible.length===1);
 for(const key of ['support','pdf','xml']){const box=$('#show-'+(key==='support'?'support':key==='pdf'?'pdf':'xml'));if(box)box.checked=workspacePanels[key]}
 localStorage.setItem('ice-workspace-panels',JSON.stringify(workspacePanels));
}
$('#show-support').onchange=e=>{workspacePanels.support=e.target.checked;applyWorkspacePanels()};
$('#show-pdf').onchange=e=>{workspacePanels.pdf=e.target.checked;applyWorkspacePanels()};
$('#show-xml').onchange=e=>{workspacePanels.xml=e.target.checked;applyWorkspacePanels()};
$('#fullscreen-workspace').onclick=()=>toggleFullscreen($('#workspace'));
document.addEventListener('fullscreenchange',()=>{$('#fullscreen-workspace').textContent=document.fullscreenElement===$('#workspace')?'Exit full screen':'Full screen'});
applyWorkspacePanels();
async function clearJobs(ids,all=false){if(!all&&!ids.length){toast('Select files using the checkboxes first.');return}if(!confirm(all?'Clear all finished files and their saved work? This cannot be undone.':'Clear '+ids.length+' selected file(s) and saved work? This cannot be undone.'))return;try{const result=await api('/api/clear',{job_ids:ids,all});if(result.removed.includes(J?.id)){J=null;dirty=false;xmlDirty=false}await loadJobs();paint();toast(result.removed.length+' file(s) cleared.'+(result.skipped.length?' '+result.skipped.length+' processing files were skipped.':''))}catch(e){toast(e.message)}}
async function downloadSelected(ids=[...selectedJobs],include_sources=false,filename='ICE_selected_articles.zip'){if(!ids.length){toast('Select files using the checkboxes first.');return}try{const r=await fetch('/api/export-batch',{method:'POST',headers:{'Content-Type':'application/json','X-ICE-Token':session.token},body:JSON.stringify({job_ids:ids,include_sources})});if(!r.ok)throw new Error((await r.json()).error);downloadBlob(await r.blob(),filename);toast('Article ZIP downloaded.')}catch(e){toast(e.message)}}
function batchDownloadDialog(ids=[...selectedJobs],all=false){if(!ids.length){toast(all?'There are no files to export.':'Select files using the checkboxes first.');return}modal((all?'Export all ':'Download ')+ids.length+(all?' article(s)':' selected article(s)'),`<p>The ZIP includes one XML and audit record for each ready article, grouped by package. Files still processing are listed as skipped in the manifest. Informational findings never block export; XML validation is recorded in the manifest.</p><label class="check"><input id="include-sources" type="checkbox"> Include original PDF, API XML, Scrapping XML and HTML documents</label><button id="start-batch-download" class="primary">Download ZIP</button>`);$('#start-batch-download').onclick=async()=>{const sources=$('#include-sources').checked;$('#dialog').close();await downloadSelected(ids,sources,all?'ICE_all_articles.zip':'ICE_selected_articles.zip')}}
async function exportToFolders(){const ids=[...selectedJobs];if(!ids.length){toast('Select files to export first.');return}if(!window.showDirectoryPicker){toast('This browser cannot choose a folder. Download the selected ZIP instead.');return}try{do{const folder=await showDirectoryPicker({mode:'readwrite'});for(const id of ids){const job=await api('/api/jobs/'+id);if(job.status!=='READY')continue;const pkg=await folder.getDirectoryHandle((job.package_name||'Package').replace(/[\\/:*?"<>|]/g,'_'),{create:true});const stem=(job.article_id||'article').replace(/[\\/:*?"<>|]/g,'_');const validation=job.validation||{},name=stem+(validation.profile_valid?'_READY':'_INVALID_DRAFT')+'.xml';const file=await pkg.getFileHandle(name,{create:true}),stream=await file.createWritable();await stream.write(job.xml||'');await stream.close();const audit=await pkg.getFileHandle(stem+'_audit.json',{create:true}),aw=await audit.createWritable();await aw.write(JSON.stringify({events:job.audit,issues:job.issues,triage:job.triage,validation:job.validation},null,2));await aw.close()}toast(ids.length+' file(s) exported to the selected folder.')}while(confirm('Export the same selected files to another folder?'))}catch(e){if(e.name!=='AbortError')toast('Folder export: '+e.message)}}
function syncDashboard(){document.body.classList.toggle('dashboard-collapsed',dashboardCollapsed);$('#dashboard-toggle').textContent=dashboardCollapsed?'▾ Expand dashboard':'▴ Collapse dashboard';$('#dashboard-toggle').setAttribute('aria-expanded',String(!dashboardCollapsed))}$('#dashboard-toggle').onclick=()=>{dashboardCollapsed=!dashboardCollapsed;sessionStorage.setItem('ice-dashboard-collapsed',dashboardCollapsed?'1':'0');syncDashboard()};syncDashboard();
$('#select-all').onchange=e=>{selectedJobs=new Set(e.target.checked?jobs.map(j=>j.id):[]);paintJobs()};$('#clear-selected').onclick=()=>clearJobs([...selectedJobs]);$('#clear-all').onclick=()=>clearJobs([],true);$('#download-selected').onclick=()=>batchDownloadDialog();$('#export-all').onclick=()=>batchDownloadDialog(jobs.map(j=>j.id),true);$('#export-folders').onclick=exportToFolders;
$('#fullscreen-support').onclick=()=>toggleFullscreen($('#support-rail'));$('#fullscreen-review').onclick=()=>toggleFullscreen($('#review-panel'));$('#compare-open').onclick=()=>compareDialog();
