$('#close-dialog').onclick=()=>$('#dialog').close();$('#upload').onclick=$('#empty-upload').onclick=()=>$('#files').click();$('#zips').onclick=()=>$('#zip-files').click();$('#folder').onclick=()=>$('#folders').click();$('#files').onchange=e=>{importFiles([...e.target.files]);e.target.value=''};$('#zip-files').onchange=e=>{importFiles([...e.target.files]);e.target.value=''};$('#folders').onchange=e=>{importFiles([...e.target.files]);e.target.value=''};
$('#import-report').onclick=showImportReport;
