$('#settings').onclick=()=>{const s=session.settings;modal('Settings',`<p class="notice blue">Processing uses local parsers and rules. External Python network connections are blocked. No LLM API keys are used.</p><div class="field"><label>Local Tesseract executable (optional, for scanned PDFs)</label><input id="tesseract" value="${esc(s.tesseract_path)}" placeholder="C:\\Program Files\\Tesseract-OCR\\tesseract.exe"></div><label class="check"><input type="checkbox" id="dash-setting" ${s.equivalent_dashes?'checked':''}>Treat em dash and double hyphen as typography-equivalent in titles</label><h3>Default delivery values for new articles</h3>${['supplier_id','source_id','order_id','parcel_id'].map(k=>`<div class="field"><label>${k.replaceAll('_',' ')}</label><input data-setting="${k}" value="${esc(s[k])}"></div>`).join('')}<button id="save-settings" class="primary">Save settings</button><p class="small muted">Existing articles keep their delivery fields. Edit those under Metadata. Client XSD validation is not available until a schema integration is supplied.</p>`);$('#save-settings').onclick=async()=>{const next={tesseract_path:$('#tesseract').value,equivalent_dashes:$('#dash-setting').checked};$$('[data-setting]').forEach(e=>next[e.dataset.setting]=e.value);session.settings=await api('/api/settings',next);$('#dialog').close();toast('Settings saved.')}};
